"use client";

import React, { useState } from "react";
import Link from "next/link";
import { usePathname, useRouter } from "next/navigation";
import {
  Menu,
  X,
  ArrowLeft,
  Info,
  Mail,
  HelpCircle,
  RefreshCcw,
  Truck,
} from "lucide-react";

const menuItems = [
  {
    id: "about",
    label: "About Us",
    href: "/help/about",
    icon: <Info size={20} />,
  },
  {
    id: "contact",
    label: "Contact Us",
    href: "/help/contact",
    icon: <Mail size={20} />,
  },
  {
    id: "shipping",
    label: "Shipping",
    href: "/help/shipping",
    icon: <Truck size={20} />,
  },
  {
    id: "faq",
    label: "FAQ",
    href: "/help/faq",
    icon: <HelpCircle size={20} />,
  },
];

export default function HelpLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  const [isOpen, setIsOpen] = useState(false);
  const pathname = usePathname();
  const router = useRouter();

  return (
    <div className="min-h-screen bg-background text-foreground">
      {/* --- STICKY NAV --- */}
      <header className="fixed top-0 z-50 w-full border-b border-border bg-background/80 backdrop-blur-md">
        <div className="max-w-7xl mx-auto h-20 px-6 flex items-center justify-between">
          <button
            onClick={() => router.back()}
            className="flex items-center gap-2 group"
          >
            <div className="p-2 rounded-full group-hover:bg-background-muted transition-colors">
              <ArrowLeft size={20} />
            </div>
          </button>

          <span className="text-xs font-black uppercase tracking-[0.3em]">
            Help Center
          </span>

          <button
            onClick={() => setIsOpen(true)}
            className="flex items-center gap-3"
          >
            <div className="p-2.5 bg-brand text-brand-foreground rounded-full">
              <Menu size={20} />
            </div>
          </button>
        </div>
      </header>

      {/* --- FULLSCREEN MENU OVERLAY --- */}
      <div
        className={`fixed inset-0 z-[60] bg-background transition-transform duration-500 ${
          isOpen ? "translate-x-0" : "translate-x-full"
        }`}
      >
        <div className="h-20 px-6 flex items-center justify-end max-w-7xl mx-auto">
          <button onClick={() => setIsOpen(false)}>
            <X size={32} />
          </button>
        </div>
        <nav className="max-w-xl mx-auto px-6 py-20 flex flex-col gap-4">
          {menuItems.map((item) => (
            <Link
              key={item.id}
              href={item.href}
              onClick={() => setIsOpen(false)}
              className={`flex items-center gap-6 p-8 rounded-[2rem] border transition-all ${
                pathname === item.href
                  ? "bg-brand text-brand-foreground border-brand"
                  : "bg-background-muted border-transparent hover:border-border"
              }`}
            >
              {item.icon}
              <span className="text-2xl font-black uppercase italic">
                {item.label}
              </span>
            </Link>
          ))}
        </nav>
      </div>

      {/* --- UNIQUE PAGE CONTENT --- */}
      <main>{children}</main>
    </div>
  );
}
